-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS public;

CREATE SEQUENCE IF NOT EXISTS public.detection_paths_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS public.detection_paths (
    id integer NOT NULL,
    root_cause_id integer NOT NULL,
    vendor_id smallint NOT NULL,
    min_version character varying(20),
    max_version character varying(20),
    name character varying(200),
    description text,
    path_type character varying(20) DEFAULT 'authored'::character varying NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    superseded_by_id integer,
    path_id character varying(80) NOT NULL,
    CONSTRAINT detection_paths_path_type_check CHECK (((path_type)::text = ANY (ARRAY[('authored'::character varying)::text, ('learned'::character varying)::text, ('hybrid'::character varying)::text])))
);

ALTER TABLE public.detection_paths ALTER COLUMN id SET DEFAULT nextval('public.detection_paths_id_seq'::regclass);
ALTER SEQUENCE public.detection_paths_id_seq OWNED BY public.detection_paths.id;

